	/**
	* Labyrinth Tracker
	* Detects cleared combat rooms via WebSocket events and records per-monster best recommendedLevel
	*/
	var STORAGE_KEY_PREFIX = "monsterBestLevels";
	var STORE_NAME = "labyrinth";
