			const sepSpan = document.createElement("span");
			sepSpan.style.color = "#888";
			sepSpan.textContent = " / ";
			const bidSpan = document.createElement("span");
			bidSpan.className = "mwi-lsp-bid";
			bidSpan.style.color = src_core_config_js.default.COLOR_INVBADGE_BID;
			bidSpan.textContent = (0, src_utils_formatters_js.formatKMB)(price.bid);
			container.appendChild(askSpan);
