			enhancingSpeed: src_core_data_manager_js.default.getCommunityBuffLevel("/community_buff_types/enhancing_speed") || 0,
			gatheringQuantity: src_core_data_manager_js.default.getCommunityBuffLevel("/community_buff_types/gathering_quantity") || 0,
