	async function runLabyrinthSimulation(params, onProgress) {
		const { gameData, playerDTOs, zoneHrid, monsterHrid, roomLevel, crates, hours, communityBuffs, labyrinthCombatBuffs } = params;
		const guildCombatBuffs = playerDTOs[0]?.guildCombatBuffs;
		const extraBuffs = [...buildExtraBuffs(communityBuffs, guildCombatBuffs), ...labyrinthCombatBuffs || []];
		const ONE_HOUR_NS = 36e11;
		cancelSimulation();
		const result = await runWorkerChunk({
			type: "start_simulation",
			taskId: ++taskIdCounter,
			gameData,
			playerDTOs,
			zoneHrid,
			difficultyTier: 0,
			simulationTimeLimit: hours * ONE_HOUR_NS,
			extraBuffs,
			labyrinth: {
				monsterHrid,
				roomLevel,
				crates: crates || []
			}
		}, onProgress);
		if (onProgress) onProgress(100);
		return result;
	}
