				if (importInput) (0, src_utils_react_input_js.setReactInputValue)(importInput, JSON.stringify(exportObj), { focus: false });
				else console.error("[Toolasha Combat Sim] Import input field not found");
				const importButton = document.querySelector("button#buttonImportSet");
