							currentHrid: mainHandEquip.hrid,
							currentLevel: enhLevel,
							upgradeHrid: itemHrid,
							upgradeLevel: enhLevel,
							addedSlots: { "/equipment_types/two_hand": {
								hrid: itemHrid,
								enhancementLevel: enhLevel
							} },
